import type { NextConfig } from "next";

const config: NextConfig = {
  // Default server output: `next start` serves it directly — the same command the shared
  // `--deploy <target>` Dockerfile's CMD runs, so the two templates compose with zero extra
  // wiring. (Swap to `output: "standalone"` + `node server.js` yourself for a slimmer image —
  // that pairs with a different Dockerfile CMD than the shared one this generator ships.)
  reactStrictMode: true,
  // The security-response floor: nosniff, deny framing, HSTS, a conservative referrer + permissions
  // policy. Extend/relax per route as your app grows (e.g. embedding needs its own X-Frame-Options).
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "X-Frame-Options", value: "DENY" },
          {
            key: "Strict-Transport-Security",
            value: "max-age=63072000; includeSubDomains; preload",
          },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
          {
            key: "Permissions-Policy",
            value: "geolocation=(), microphone=(), camera=()",
          },
        ],
      },
    ];
  },
};

export default config;

{
  "generator": "create-caisson",
  "ok": true
}

// Server Action example for `@caisson-sh/tenancy-rls`: tenant context is bound PER CALL inside
// `withTenant` — never cached across requests. The session's `accountId` (never a client-supplied
// param) is the only value trusted for tenant scoping; RLS on the `notes` table does the rest
// (fail-closed — a query outside `withTenant` sees nothing, ADR-0005). Server Actions never
// receive a `Request`, so the session comes off `next/headers`'s cookie jar instead of
// `resolveSessionFromRequest`.
"use server";

import { cookies } from "next/headers";
import { requireSession } from "@caisson-sh/auth";
import { withTenant } from "@caisson-sh/tenancy-rls";
import { SESSION_COOKIE, verifySessionToken } from "../../lib/auth";
import { db } from "../../lib/db";

export interface Note {
  id: string;
  body: string;
}

/** Illustrative — add a migration for a `notes(id, account_id, body, created_at)` table (with
 *  `@caisson-sh/tenancy-rls`'s `buildTenantPolicySql("notes")` RLS policy) before this runs for real. */
export async function listNotes(): Promise<Note[]> {
  const jar = await cookies();
  const session = requireSession(
    verifySessionToken(jar.get(SESSION_COOKIE)?.value),
  );
  return withTenant(db, session.accountId, async (tx) => {
    const { rows } = await tx.query<Note>(
      "SELECT id, body FROM notes ORDER BY created_at DESC LIMIT 20",
    );
    return rows;
  });
}

// Server Action example: enqueuing a job (@caisson-sh/jobs `JobQueue.enqueue`) instead of sending
// email inline — the caller returns immediately, the queue's driver retries the send on failure.
"use server";

import { z } from "zod";
import { queue } from "../../lib/jobs";

const NotifyInput = z.object({ email: z.string().email() }).strict();

export async function notifySignup(input: unknown): Promise<void> {
  const { email } = NotifyInput.parse(input);
  await queue.enqueue("send-welcome-email", { to: email });
}

// Billing webhook Route Handler — a STUB wired against the open `BillingProvider` PORT
// (@caisson-sh/billing, ADR-0017): `verifyAndParse` turns a raw provider payload into the
// provider-agnostic `DomainBillingEvent`. The port's concrete driver factories (Stripe/Paddle/
// LemonSqueezy/Polar) are the `@caisson-sh/billing-orchestration` package — swap
// `getBillingProvider()` for one of those (or your own port implementation, using the open raw
// verifiers `verifyStripeWebhook`/`verifyPaddleWebhook`/… also exported from `@caisson-sh/billing`).
import type { NextRequest } from "next/server";
import type { BillingProvider } from "@caisson-sh/billing";
import { toErrorResponse } from "@caisson-sh/kernel";

function getBillingProvider(): BillingProvider {
  throw new Error(
    "wire a BillingProvider driver here — e.g. @caisson-sh/billing-orchestration's createStripeBilling()",
  );
}

export async function POST(request: NextRequest): Promise<Response> {
  const rawBody = await request.text();
  const signature = request.headers.get("stripe-signature") ?? "";

  try {
    const event = getBillingProvider().verifyAndParse(rawBody, signature);
    if (event === null) {
      // An event type this provider maps to `null` on purpose — ack, no-op.
      return new Response(null, { status: 200 });
    }

    switch (event.type) {
      case "purchase.completed":
      case "subscription.created":
        // Wire your entitlement/credit grant here (see @caisson-sh/credits for the ledger primitive).
        break;
      case "subscription.updated":
      case "subscription.canceled":
      case "refund.completed":
      case "invoice.paid":
        // Wire the matching downstream effect for this event.
        break;
    }

    return new Response(null, { status: 200 });
  } catch (error) {
    const { status, body } = toErrorResponse(error);
    return Response.json(body, { status });
  }
}

// Route Handler example: the same session verification `proxy.ts` uses, enforced with
// `requireSession` (throws `AuthnError` on no session) and mapped to a client-safe envelope with
// `toErrorResponse` (@caisson-sh/kernel, ADR-0019's typed-error → HTTP-status mapping).
import type { NextRequest } from "next/server";
import { requireSession } from "@caisson-sh/auth";
import { toErrorResponse } from "@caisson-sh/kernel";
import { resolveSessionFromRequest } from "../../../lib/auth";

export function GET(request: NextRequest): Response {
  try {
    const session = requireSession(resolveSessionFromRequest(request));
    return Response.json({
      userId: session.userId,
      accountId: session.accountId,
      role: session.role,
    });
  } catch (error) {
    const { status, body } = toErrorResponse(error);
    return Response.json(body, { status });
  }
}

