import { describe, expect, test } from "bun:test";
import { readdirSync } from "node:fs";
import { join } from "node:path";

// Golden-file regression: every committed `__golden__/*.json`
// baseline must parse and be a non-empty object. As you add your installed modules' fixtures,
// they are covered here automatically. Run `BLESS=1 bun test` to re-bless after a reviewed change.
const goldenDir = join(import.meta.dir, "__golden__");

describe("golden baselines", () => {
  const fixtures = readdirSync(goldenDir)
    .filter((name) => name.endsWith(".json"))
    .sort();

  for (const name of fixtures) {
    test(`${name} is a valid baseline`, async () => {
      const data = (await Bun.file(join(goldenDir, name)).json()) as Record<
        string,
        unknown
      >;
      expect(data).toBeDefined();
      expect(Object.keys(data).length).toBeGreaterThan(0);
    });
  }
});

// Provider-agnostic AI config via `@caisson-sh/ai-config`: the provider/model is always chosen from a
// lane map, never hardcoded — swapping providers is a config change, not a code change. This
// resolves WHICH provider/model backs a lane; the key VALUE is never read here — a caller reads
// `process.env[config.apiKeyEnv]` right before its own SDK call.
import { parseAiSettings, resolveProvider } from "@caisson-sh/ai-config";
import type { ProviderConfig } from "@caisson-sh/ai-config";

/** Your lane map — move this into your own config file/DB row as the app grows; the shape stays
 *  the same. Add a lane per use case (e.g. "summarize", "classify") rather than one global model. */
const settings = parseAiSettings({
  defaultLane: "default",
  lanes: {
    default: {
      provider: "openai",
      model: "gpt-4o-mini",
      apiKeyEnv: "OPENAI_API_KEY",
    },
  },
});

export function getAiProviderConfig(lane?: string): ProviderConfig {
  return resolveProvider(settings, lane);
}

// Session resolution for the account JWT `@caisson-sh/auth` issues (EdDSA/Ed25519, `signAccountJwt`
// / `verifyAccountJwt`). This app only ever VERIFIES — the private key stays with whatever issues
// the token (better-auth's JWT plugin, or your own issuer service); `AUTH_JWT_PUBLIC_KEY` is the
// base64 SPKI DER public half from `generateAccountKeyPair()`.
import { createPublicKey, type KeyObject } from "node:crypto";
import type { NextRequest } from "next/server";
import { ConfigError } from "@caisson-sh/kernel";
import { verifyAccountJwt } from "@caisson-sh/auth";
import type { SessionContext } from "@caisson-sh/auth";

/** The cookie carrying the account JWT. Rename to match your issuer's cookie if different. */
export const SESSION_COOKIE = "caisson_session";

let cachedPublicKey: KeyObject | undefined;

function getPublicKey(): KeyObject {
  if (cachedPublicKey === undefined) {
    const encoded = process.env.AUTH_JWT_PUBLIC_KEY;
    if (encoded === undefined) {
      throw new ConfigError("AUTH_JWT_PUBLIC_KEY is not set");
    }
    cachedPublicKey = createPublicKey({
      key: Buffer.from(encoded, "base64"),
      format: "der",
      type: "spki",
    });
  }
  return cachedPublicKey;
}

/**
 * Verify a raw JWT string. Never throws: a missing/invalid/expired token resolves to `null` — the
 * same "no session" shape `SessionProvider.resolveSession` returns. Callers enforce it with
 * `requireSession` from `@caisson-sh/auth` (throws `AuthnError`, map it with `toErrorResponse`).
 */
export function verifySessionToken(
  token: string | undefined,
): SessionContext | null {
  if (token === undefined) return null;
  try {
    return verifyAccountJwt(token, getPublicKey());
  } catch {
    return null;
  }
}

/**
 * Resolve the session straight off an incoming request — `proxy.ts` and Route Handlers both get a
 * real `NextRequest`. Next 16 runs `proxy.ts` on the Node.js runtime by default (unlike the old
 * Edge-only `middleware.ts`), so `node:crypto`'s EdDSA verify works here with no edge shim.
 * Server Actions never see a `Request` — read the cookie via `next/headers`'s `cookies()` instead
 * and call `verifySessionToken` directly (see `src/app/actions/notes.ts`).
 */
export function resolveSessionFromRequest(
  request: NextRequest,
): SessionContext | null {
  return verifySessionToken(request.cookies.get(SESSION_COOKIE)?.value);
}

// The `@caisson-sh/tenancy-rls` `Transactor` — the canonical node-postgres adapter
// (`createPgTransactor`) over a Pool this app owns. The pool is constructed lazily (on first
// `.transaction()` call, not at import time) so a missing `DATABASE_URL` never breaks a
// build/typecheck, only a real query at runtime.
import { ConfigError } from "@caisson-sh/kernel";
import {
  createPgPool,
  createPgTransactor,
  type TenantExecutor,
  type Transactor,
} from "@caisson-sh/tenancy-rls";
import type { Pool } from "pg";

let pool: Pool | undefined;

function getPool(): Pool {
  if (pool === undefined) {
    const connectionString = process.env.DATABASE_URL;
    if (connectionString === undefined) {
      throw new ConfigError("DATABASE_URL is not set");
    }
    pool = createPgPool(connectionString);
  }
  return pool;
}

/** The `Transactor` every `withTenant`/`withUser` call in this app runs against. Swap the driver
 *  (a different Postgres client, PGlite for local dev) by implementing this same interface. */
export const db: Transactor = {
  transaction<T>(fn: (tx: TenantExecutor) => Promise<T>): Promise<T> {
    return createPgTransactor(getPool()).transaction(fn);
  },
};

// Transactional email via the `@caisson-sh/email` `Emailer` port. Resend in production
// (`RESEND_API_KEY` + `RESEND_FROM` set); an in-memory capture driver otherwise — safe default for
// local dev and CI, never touches the network. Swap in `@caisson-sh/email`'s Postmark/SES/SMTP
// drivers the same way; every caller only ever depends on the `Emailer` port.
import { createCaptureEmailer, createResendEmailer } from "@caisson-sh/email";
import type { Emailer } from "@caisson-sh/email";

function createEmailer(): Emailer {
  const apiKey = process.env.RESEND_API_KEY;
  const from = process.env.RESEND_FROM;
  if (apiKey !== undefined && from !== undefined) {
    return createResendEmailer({ apiKey, from });
  }
  return createCaptureEmailer();
}

export const emailer: Emailer = createEmailer();

export async function sendWelcomeEmail(to: string): Promise<void> {
  await emailer.send({ to, template: "welcome", data: {} });
}

// Background jobs via the `@caisson-sh/jobs` `JobQueue` port. `createInMemoryQueue` runs a task's
// handler inline (synchronous, no daemon) — fine for dev/tests, and every caller only ever depends
// on the `JobQueue` port, so swapping in the durable pg-boss/Trigger.dev driver later is a config
// change, not a rewrite.
import { z } from "zod";
import { createInMemoryQueue, defineTask } from "@caisson-sh/jobs";
import type { JobQueue } from "@caisson-sh/jobs";
import { sendWelcomeEmail } from "./email";

const sendWelcomeEmailTask = defineTask(
  "send-welcome-email",
  z.object({ to: z.string().email() }).strict(),
  async (payload) => {
    await sendWelcomeEmail(payload.to);
  },
);

export const queue: JobQueue = createInMemoryQueue([sendWelcomeEmailTask]);

// Next 16 renamed `middleware.ts` to `proxy.ts` (same request-interception mechanism, new name +
// Node.js runtime by default). Gates everything under /dashboard: no valid session → redirect to
// /login. Adjust `config.matcher` for the routes your app actually protects.
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { resolveSessionFromRequest } from "./lib/auth";

export function proxy(request: NextRequest): NextResponse {
  const session = resolveSessionFromRequest(request);
  if (session === null) {
    const loginUrl = new URL("/login", request.url);
    loginUrl.searchParams.set("from", request.nextUrl.pathname);
    return NextResponse.redirect(loginUrl);
  }
  return NextResponse.next();
}

export const config = {
  matcher: "/dashboard/:path*",
};
